package com.mathengine.data;import android.content.Context;import org.json.JSONArray;import org.json.JSONObject;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
public final class OfflineCurrencyRates{private final Map<String,Map<String,Double>> rates=new HashMap<>();public OfflineCurrencyRates(Context c)throws Exception{String json=read(c,"default_data/units_currency");JSONArray rows=new JSONObject(json).getJSONArray("rate");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);String a=row.getString("n1").toUpperCase(Locale.ROOT),b=row.getString("n2").toUpperCase(Locale.ROOT);double r=Double.parseDouble(row.getString("r"));if(r>0&&Double.isFinite(r)){rates.computeIfAbsent(a,k->new HashMap<>()).put(b,r);rates.computeIfAbsent(b,k->new HashMap<>()).put(a,1d/r);}}}
public double convert(double amount,String from,String to){String a=from.trim().toUpperCase(Locale.ROOT),b=to.trim().toUpperCase(Locale.ROOT);if(a.equals(b))return amount;Map<String,Double> d=rates.get(a);if(d!=null&&d.containsKey(b))return amount*d.get(b);if(d!=null)for(Map.Entry<String,Double> e:d.entrySet()){Map<String,Double>s=rates.get(e.getKey());if(s!=null&&s.containsKey(b))return amount*e.getValue()*s.get(b);}throw new IllegalArgumentException("No offline rate for "+a+" → "+b);}
private static String read(Context c,String p)throws Exception{try(InputStream in=c.getAssets().open(p);ByteArrayOutputStream o=new ByteArrayOutputStream()){byte[]b=new byte[8192];int n;while((n=in.read(b))!=-1)o.write(b,0,n);return o.toString(StandardCharsets.UTF_8.name());}}
}
